window.kbPageData["views/practice/s-33e33ba24dd315ec"] = {"key":"practice/s-33e33ba24dd315ec","state":{"route":"practice/s-33e33ba24dd315ec"},"tree":"<a data-toc-link href=\"#skills/xingce\">行测技能首页</a><details data-branch=\"module-政治理论\"><summary>政治理论</summary><div class=\"tocChildren\"><a data-toc-link href=\"#skills/xingce/%E6%94%BF%E6%B2%BB%E7%90%86%E8%AE%BA\">专题概览</a><a data-toc-link href=\"#practice/theory\">理论原理与材料对应</a><a data-toc-link href=\"#practice/policy\">政策目标与具体举措</a><a data-toc-link href=\"#practice/institutions\">制度、文件与规范表述</a></div></details><details data-branch=\"wording\"><summary>时政措辞辨析</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/wording\">专题概览</a><a data-toc-link href=\"#practice/wording/conditions\">必须、可以与例外条件</a><a data-toc-link href=\"#practice/wording/degree\">强度、进度与结果</a><a data-toc-link href=\"#practice/wording/roles\">首要任务、根本保证与具体分工</a><a data-toc-link href=\"#practice/wording/scope\">主体、对象与适用范围</a><a data-toc-link href=\"#practice/wording/authority\">宪法、党章与制度权限</a><a data-toc-link href=\"#practice/wording/direction\">方向、分类与历史阶段</a></div></details><details data-branch=\"module-常识判断\"><summary>常识判断</summary><div class=\"tocChildren\"><a data-toc-link href=\"#skills/xingce/%E5%B8%B8%E8%AF%86%E5%88%A4%E6%96%AD\">专题概览</a><a data-toc-link href=\"#practice/law\">法律规则与案例</a><a data-toc-link href=\"#practice/science\">科技、地理与生活现象</a><a data-toc-link href=\"#practice/public-affairs\">经济、政策与公共管理</a><a data-toc-link href=\"#practice/history-culture\">历史人文与国情</a></div></details><details data-branch=\"module-言语理解与表达\"><summary>言语理解与表达</summary><div class=\"tocChildren\"><a data-toc-link href=\"#skills/xingce/%E8%A8%80%E8%AF%AD%E7%90%86%E8%A7%A3%E4%B8%8E%E8%A1%A8%E8%BE%BE\">专题概览</a><a data-toc-link href=\"#practice/s-bc177199c1351631\">根据语境辨析词语</a><a data-toc-link href=\"#practice/s-gist\">主旨与作者意图</a><a data-toc-link href=\"#practice/s-c5eac332ba86912d\">结合搭配对象辨析用词</a><a data-toc-link href=\"#practice/s-ef0f414c890a2427\">核对原文与选项</a><a data-toc-link href=\"#practice/s-4eebda7bdff18647\">补全语句衔接</a><a data-toc-link href=\"#practice/s-871196fcda246b8d\">语句排序与插入</a><a data-toc-link href=\"#practice/s-94e5b1e84b4945ab\">推断下文</a><a data-toc-link href=\"#practice/s-0a0bc5508fefda64\">拟定文段标题</a><a data-toc-link href=\"#practice/s-8713d7d1007a8167\">词句含义与指代</a><a data-toc-link href=\"#practice/s-84ff0f0fbbe378d8\">结合语境辨析成语</a><a data-toc-link href=\"#practice/s-b2f959b1b4484115\">辨认材料支持的观点</a><a data-toc-link href=\"#practice/s-300f89e88263b685\">通过转折定位文段重心</a><a data-toc-link href=\"#practice/s-4159fb5ba3bc2963\">运用文段给出的标准判断实例</a></div></details><details data-branch=\"module-数量关系\"><summary>数量关系</summary><div class=\"tocChildren\"><a data-toc-link href=\"#skills/xingce/%E6%95%B0%E9%87%8F%E5%85%B3%E7%B3%BB\">专题概览</a><a data-toc-link href=\"#practice/s-ac5c371e800baa75\">几何构造与度量</a><a data-toc-link href=\"#practice/s-d968fce424f6218d\">等量关系列方程</a><a data-toc-link href=\"#practice/s-c0f6c7e3ae9d902e\">排列组合与分类计数</a><a data-toc-link href=\"#practice/s-bfe8437fe159274c\">拆分与改写数列</a><a data-toc-link href=\"#practice/s-4d945e4b584e20e6\">工程量与效率</a><a data-toc-link href=\"#practice/s-a678755b344c536e\">行程、相遇与追及</a><a data-toc-link href=\"#practice/s-fa618aa0e5554dde\">事件概率与几何概率</a><a data-toc-link href=\"#practice/s-36722f3b0a111400\">周期与余数</a><a data-toc-link href=\"#practice/s-36bcdccc44445c07\">用容斥计算重叠人数</a><a data-toc-link href=\"#practice/s-27070cd6f8f1808e\">约束条件下求最值</a><a data-toc-link href=\"#practice/s-55b69f4a0862f7f1\">成本、售价与收入</a><a data-toc-link href=\"#practice/s-98ca154ecf4968d7\">利用整数条件求解不定方程</a><a data-toc-link href=\"#practice/s-7ee6e0e28c7c40e3\">辨认数列递推或周期规律</a><a data-toc-link href=\"#practice/s-261f4b85ee542fe2\">代入选项验算</a><a data-toc-link href=\"#practice/s-4c82ef55d2b649c7\">数列作差与作商</a><a data-toc-link href=\"#practice/s-5864586ebd669b08\">等差数列求项与求和</a><a data-toc-link href=\"#practice/s-7c91e017f98bac24\">用比例赋值简化计算</a><a data-toc-link href=\"#practice/s-f6792163b580976b\">按溶质量守恒计算混合与稀释</a><a data-toc-link href=\"#practice/s-b0dec29a0ef842cb\">按边权选择最小生成树的边</a><a data-toc-link href=\"#practice/s-ff03c13adcbe7233\">端点与间隔计数</a></div></details><details data-branch=\"module-判断推理\" open><summary>判断推理</summary><div class=\"tocChildren\"><a data-toc-link href=\"#skills/xingce/%E5%88%A4%E6%96%AD%E6%8E%A8%E7%90%86\">专题概览</a><a data-toc-link href=\"#practice/s-conditions\">按题内定义核对案例条件</a><a data-toc-link href=\"#practice/s-d45531f0ca63ae30\">类比关系与词项顺序</a><a data-toc-link href=\"#practice/s-aa16640dd943508a\">多条件对应与排序</a><a data-toc-link href=\"#practice/s-c96dc3b8ef59659c\">图形元素计数</a><a data-toc-link href=\"#practice/s-tiles\">按边界重组平面碎片</a><a data-toc-link href=\"#practice/s-2ee7513507dfe397\">用证据加强结论</a><a data-toc-link href=\"#practice/s-afb05982fcc9a31c\">判断展开图的邻面、图案和公共边</a><a data-toc-link href=\"#practice/s-449334f5aeb5ea84\">图形平移、旋转与翻折</a><a data-toc-link href=\"#practice/s-b675a81beafb818e\">立体视图与截面</a><a data-toc-link href=\"#practice/s-449c824eeb0b7f3d\">对称与形状属性</a><a data-toc-link href=\"#practice/s-bd23484a6c3aa41a\">检验论证成立的条件</a><a data-toc-link href=\"#practice/s-8e029448a5228c68\">条件推理与结论范围</a><a data-toc-link href=\"#practice/s-26718cf11a50ed78\">构词与词义关系</a><a data-toc-link href=\"#practice/s-cd83588b8b1f05cb\">事件关系与语序</a><a data-toc-link href=\"#practice/s-ae670e69128d8e55\">削弱因果推断</a><a data-toc-link href=\"#practice/s-73b5da0d39715bb4\">辨认图形接触、相交和公共边</a><a data-toc-link href=\"#practice/s-e207f62725dca283\">梳理论证链</a><a data-toc-link href=\"#practice/s-ca43cd3fbda05045\">比对概念的外延和分类关系</a><a data-toc-link href=\"#practice/s-9f74c42e488abf6f\">比较论证结构</a><a data-toc-link href=\"#practice/s-49e530b3a2c0cd4c\">叠加与黑白变化</a><a data-toc-link href=\"#practice/s-599d7fb5a061494c\">图形连通与分离</a><a data-toc-link href=\"#practice/s-182392c898d56a84\">对象的属性、构成与用途</a><a data-toc-link href=\"#practice/s-f3b05c49f6712148\">根据真假数量确定陈述真值</a><a data-toc-link href=\"#practice/s-4e6dc1eac45ccce0\">检验样本是否支持总体推断</a><a data-toc-link href=\"#practice/s-9f1e8d490dc6971d\">判断证据能否削弱结论</a><a data-toc-link href=\"#practice/s-2a7fe675bd0d6265\">图形位置与方向</a><a data-toc-link href=\"#practice/s-ba9cd0f2f572724c\">按指标定义计算比值</a><a data-toc-link href=\"#practice/s-1e26b8e07773b68a\">数量约束与枚举</a><a data-toc-link href=\"#practice/s-db4885a9ca6b54c2\">按规则比较与排序</a><a data-toc-link href=\"#practice/s-fbc7bd8e0e436bca\">按图示规则追踪关系</a><a data-toc-link href=\"#practice/s-33e33ba24dd315ec\" aria-current=\"page\">解释现象与差异</a><a data-toc-link href=\"#practice/s-15c5a161061d35d8\">比较图形涂色面积的变化</a></div></details><details data-branch=\"module-资料分析\"><summary>资料分析</summary><div class=\"tocChildren\"><a data-toc-link href=\"#skills/xingce/%E8%B5%84%E6%96%99%E5%88%86%E6%9E%90\">专题概览</a><a data-toc-link href=\"#practice/s-e9ffdd08e7f0ec51\">平均数、比值与倍数</a><a data-toc-link href=\"#practice/s-f29bc501c32a5bee\">增长量与平均增量</a><a data-toc-link href=\"#practice/s-a7ce466b25f8ea1b\">比重、部分与总体</a><a data-toc-link href=\"#practice/s-22e0d443f4e8833e\">比较比重与百分点差</a><a data-toc-link href=\"#practice/s-rates\">同比、环比与基准期</a><a data-toc-link href=\"#practice/s-base\">还原与比较基期量</a><a data-toc-link href=\"#practice/s-9d6535a8dad068a9\">分项汇总与时段还原</a><a data-toc-link href=\"#practice/s-a28704d6c4e47be4\">按阈值筛选计数</a><a data-toc-link href=\"#practice/s-6cfd92b2f027f1a1\">数据与图表匹配</a><a data-toc-link href=\"#practice/s-9fc2e5daf6bbb9d8\">按增量或增速推算达标时间</a><a data-toc-link href=\"#practice/s-bc3e3cd5b0647c96\">基期与两期比重</a><a data-toc-link href=\"#practice/s-f727adc9d8af6663\">年均与跨期增长率</a><a data-toc-link href=\"#practice/s-d495edd4c80a44de\">核对指标所需数据与统计范围</a><a data-toc-link href=\"#practice/s-ddad42966dfee84f\">指标排序与定位</a><a data-toc-link href=\"#practice/s-a889bfbec9cac071\">分项与总体增长率</a><a data-toc-link href=\"#practice/s-3a4006f35d6c4142\">集合重叠与余量界限</a><a data-toc-link href=\"#practice/s-5e5c8fdd21d132b3\">增长倍数与期末量</a><a data-toc-link href=\"#practice/s-747f2e4430a1cd1a\">比较指标差额</a><a data-toc-link href=\"#practice/s-a227494d12288056\">增速的百分点差</a><a data-toc-link href=\"#practice/s-c0d36320cd06d980\">增长贡献率</a></div></details>","packs":{"江苏 2023 A类 行测#96":"b9fb01be80899e003195254e","江苏 2023 B类 行测#92":"b9fb01be80899e003195254e","江苏 2024 A类 行测#94":"b9fb01be80899e003195254e","江苏 2025 B类 行测#94":"1c96772a055da55e438d2835"},"questions":{"江苏 2023 A类 行测#96":{"paper":"江苏 2023 A类 行测","n":96,"mod":"判断推理","src":["22304fe4c340e19d7902.pdf",20],"asrc":["be17f9afe070cf13a0fb.pdf",28]},"江苏 2023 B类 行测#92":{"paper":"江苏 2023 B类 行测","n":92,"mod":"判断推理","src":["22262c34d18cd68fbee4.pdf",19],"asrc":["b08f2713d73015eac675.pdf",28]},"江苏 2024 A类 行测#94":{"paper":"江苏 2024 A类 行测","n":94,"mod":"判断推理","src":["f8fec75f67d6d1ba5759.pdf",19],"asrc":["0126a1c8aceee632ea2b.pdf",29]},"江苏 2025 B类 行测#94":{"paper":"江苏 2025 B类 行测","n":94,"mod":"判断推理","src":["91e0d9fd02ca7ec6d61f.pdf",19],"asrc":["f2ff67a0f2a2f7e8e926.pdf",31]}},"first":{"qs":{"江苏 2023 A类 行测#96":{"paper":"江苏 2023 A类 行测","n":96,"mod":"判断推理","src":["22304fe4c340e19d7902.pdf",20],"asrc":["be17f9afe070cf13a0fb.pdf",28],"m":[],"task":"找出能解释用户很少阅读协议、又不愿授予额外权限却仍点击同意的条件。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答依赖题内假设对用户行为的解释。"},"links":[{"id":"s-33e33ba24dd315ec","label":"寻找能同时解释表面矛盾双方的条件","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"想要使用APP必须同意用户协议","why":"使用条件说明了用户为何可以保留对权限的顾虑，同时仍选择点击同意。","origin":"逐题标记"}],"stem":"手机APP为了获得一些读取信息和修改手机设置的权限， 都会提供用户协议并要求使用者同意。然而，据权威\n调查显示，大部分使用者很少或从没阅读过APP提供的用户协议,也不乐意APP有超出其功能的某些权限，但他们都\n会点击“我已阅读并同意用户协议”。\n以下哪项如果为真，最能解释上述现象？","options":["如果用户不同意手机APP所提供的用户协议，就不能使用这款 APP","通过正规平台下载的APP有平台审核其安全性，不需要下载者进行核查","很多手机APP的用户协议冗长复杂，用户无法在短时间内读完或读懂","对于某些APP来说，用户在使用过程中还能重新设定它获取的各种权限"],"answer":"A","analysis":"96. 正确答案：A\n解析：\n\n第一步：找出题干矛盾。\n大部分使用者很少或从没阅读过APP提供的用户协议，也不乐意APP有超出其功能的某些权限，但他们都会点击“我\n已阅读并同意用户协议”。\n第二步：逐一分析选项。\nA项：该项指出想要使用APP必须同意用户协议，因此即使使用者很少或从没阅读过APP提供的用户协议，也不乐意\nAPP有超出其功能的某些权限，但为了能使用该款APP不得不点击“我已阅读并同意用户协议”，可以解释题干矛盾，\n当选；\nB项：该项仅说明使用者无需担心通过正规平台下载的APP的安全性，题干中未涉及使用者下载APP的平台是否正\n规，也没有解释使用者为何在很少或从没阅读过APP提供的用户协议且不乐意APP有超出其功能的某些权限时会点\n击“我已阅读并同意用户协议”，不能解释题干矛盾，排除；\nC项：该项指出用户无法在短时间内读完或读懂APP冗长复杂的用户协议，可以解释为什么大部分使用者很少或从没\n阅读过APP提供的用户协议，但不能解释为什么在不乐意APP有超出其功能的某些权限时，还是会点击“我已阅读并\n同意用户协议”，不能解释题干矛盾，排除；\nD项：该项仅说明用户在使用过程中可以重新设定某些APP获取的各种权限，无法确定“某些APP”有多少，题干中针\n对的是手机APP这一整体，因此某些APP的情况不能解释题干矛盾，排除。\n故正确答案为A。\n【考点】\n原因解释","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false},"江苏 2023 B类 行测#92":{"paper":"江苏 2023 B类 行测","n":92,"mod":"判断推理","src":["22262c34d18cd68fbee4.pdf",19],"asrc":["b08f2713d73015eac675.pdf",28],"m":[],"task":"比较各项对两种情绪传达方式的解释，判断哪项最能说明人们更常使用表情包的原因。","current_affairs":{"state":"否","event":null,"year":null,"basis":"依据题内给出的交流现象和备选解释判断。"},"links":[{"id":"s-33e33ba24dd315ec","label":"比较不同方式的相关优势以解释偏好","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"更明确地将表情包与远程面对面交流进行了比较","why":"用与传达情绪直接相关的相对优势解释两种方式都能传情时的使用偏好。","origin":"逐题标记","originalId":"s-80e689b5d32aba52"}],"stem":"目前，智能通信工具实现了远程面对面交流，其传输的画面和声音也能准确地传达人们的表情和情绪，然而，在\n通过网络进行沟通和交流时，人们更习惯用各种表情包来传达日常生活中的喜怒哀乐，表情包已从情绪符号变成了\n网络社交利器。\n以下哪项如果为真，最能解释上述现象？","options":["大多数时候，人们并不愿意在交流中表露自己的真实表情和情绪","使用表情包比控制自己的面部表情和声音要方便容易得多","人们需要为远程面对面交流所消耗的流量支付更多费用","表情包能以一种夸张的方式传达出人们的表情和情绪"],"answer":"B","analysis":"92. 正确答案：B\n解析：\n第一步：找出题干矛盾。\n\n远程面对面交流传输的画面和声音也能准确地传达人们的表情和情绪，然而人们更习惯用各种表情包来传达日常生\n活中的喜怒哀乐。\n第二步：逐一分析选项。\nA项：该项仅说明大多数时候人们并不愿意在交流中表露自己的真实表情和情绪，并未提及相比远程面对面交流传输\n的画面和声音人们更习惯用表情包的原因，不能解释题干矛盾，排除；\nB项：该项在表情包和面对面交流中传输的画面、声音之间进行对比，说明表情包相比画面、声音在传达情绪过程中\n所具备的优势，能够解释为什么远程面对面交流传输的画面和声音也能准确地传达人们的表情和情绪，但人们更习\n惯使用各种表情包来传达情绪，可以解释题干矛盾，保留；\nC项：该项指出远程面对面交流需要支付更多的流量费用，侧面反映出使用表情包所需的流量费用可能较少，能够解\n释为什么远程面对面交流传输的画面和声音也能准确地传达人们的表情和情绪，但人们更习惯使用各种表情包来传\n达情绪，可以解释题干矛盾，保留；\nD项：该项仅说明表情包能以一种夸张的方式传达出人们的表情和情绪，并未提及相比远程面对面交流传输的画面和\n声音人们更习惯用表情包的原因，不能解释题干矛盾，排除。\n对比B、C两项，B项指出表情包在情绪传达过程中的优势，而C项是价格方面的优势，B项与题干的话题更接近，且\nB项更明确地将表情包与远程面对面交流进行了比较，因此B项解释力度更强。\n故正确答案为B。\n【考点】\n原因解释","figs":[],"state":"已标记","notes":[],"domains":[],"nature":"技能题","current":false},"江苏 2024 A类 行测#94":{"paper":"江苏 2024 A类 行测","n":94,"mod":"判断推理","src":["f8fec75f67d6d1ba5759.pdf",19],"asrc":["0126a1c8aceee632ea2b.pdf",29],"m":[],"task":"找出能同时解释今年进口巴沙鱼需求下降和国产黑鱼份额上升的变化。","current_affairs":{"state":"否","event":null,"year":null,"basis":"题内已给出市场变化及其时间比较。"},"links":[{"id":"k-0eac07e8da149ea8","label":"替代品相对价格下降可带动需求转移","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"question","quote":"随着国产黑鱼产、供、销体系完善，其价格降低","why":"两种原料可以相互替代时，一方降价会削弱另一方的价格优势。","origin":"逐题标记"},{"id":"s-33e33ba24dd315ec","label":"用同一新增因素解释同期发生的双向变化","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"但今年酸菜鱼市场对V国巴沙鱼的需求减弱，其份额逐渐被国产黑鱼占据。","why":"核对解释能否同时说明变化发生的时间以及份额转移的方向。","origin":"逐题标记","originalId":"s-0ef0258990cbd4ee"}],"stem":"近年来，V国巴沙鱼因在进口时已完成分割、切块、去刺等工序，加工成本比国产黑鱼低，一直是制作酸菜鱼的\n重要原料。但今年酸菜鱼市场对V国巴沙鱼的需求减弱，其份额逐渐被国产黑鱼占据。\n以下哪项为真，最能解释上述现象？","options":["随着国产黑鱼产、供、销体系完善，其价格降低","V国巴沙鱼进入中国需要经有关部门食品安全检测，需较长时间","过去几年爆火的以V国巴沙鱼为原料的酸菜鱼预制菜今年销售份额降低","以国产黑鱼为原料的酸菜鱼味道更鲜美，受到对价格不敏感的消费者喜爱"],"answer":"A","analysis":"94. 正确答案：A\n解析：\n第一步：找出题干矛盾。\nV国巴沙鱼加工成本比国产黑鱼低，一直是制作酸菜鱼的重要原料，但今年酸菜鱼市场对V国巴沙鱼的需求减弱，其\n份额逐渐被国产黑鱼占据。\n第二步：逐一分析选项。\nA项：该项指出国产黑鱼价格降低了，之前对V国巴沙鱼需求强是因为加工成本低，而现在随着国产黑鱼价格的降\n低，V国巴沙鱼逐渐失去价格优势，因此酸菜鱼市场就会减少对V国巴沙鱼的需求，其份额逐渐被价格降低的国产黑\n鱼占据，可以解释题干矛盾，当选；\nB项：该项指出V国巴沙鱼进入中国需要较长的检测时间，但该问题一直存在，无法解释为何“今年”酸菜鱼市场对V国\n巴沙鱼的需求减弱，其份额逐渐被国产黑鱼占据，无法解释题干矛盾，排除；\nC项：该项指出今年以V国巴沙鱼为原料的酸菜鱼预制菜销售份额降低，可以导致对V国巴沙鱼的一部分需求减弱，\n但不能解释为什么其份额逐渐被国产黑鱼占据，无法解释题干矛盾，排除；\nD项：该项指出以国产黑鱼为原料的酸菜鱼味道更鲜美，受到对价格不敏感的消费者喜爱，但该情况一直存在，不只\n出现在“今年”，且无法判断“对价格不敏感的消费者”数量多少，是否可以代表全部消费者，无法解释题干矛盾，排\n除。\n故正确答案为A。\n【考点】\n原因解释","figs":[],"state":"已标记","notes":[],"domains":["经济"],"nature":"综合题","current":false}},"materialFiles":{},"terms":{"s-33e33ba24dd315ec":{"id":"s-33e33ba24dd315ec","mode":"s","type":"判断推理","title":"解释现象与差异","qs":[],"count":4},"k-0eac07e8da149ea8":{"id":"k-0eac07e8da149ea8","mode":"k","type":"原理与机制","title":"替代品的相对价格与需求转移","qs":[],"count":1}},"questions":{}},"firstMaterials":[],"node":{"id":"s-33e33ba24dd315ec","mode":"s","title":"解释现象与差异","type":"判断推理","domain":"形式逻辑","reading":"","intro":"","priority":100,"aliases":["寻找能同时解释表面矛盾双方的条件","用同一新增因素解释同期发生的双向变化","检验原因能否解释表面矛盾的两个现象","比较不同方式的相关优势以解释偏好","解释表面矛盾的现象"],"qs":["江苏 2023 A类 行测#96","江苏 2023 B类 行测#92","江苏 2024 A类 行测#94","江苏 2025 B类 行测#94"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"method":"把需要解释的两个事实并列，寻找能让两者同时成立的条件。","subject":"行测","publishedSets":[{"name":"解释现象与差异","ids":["江苏 2023 A类 行测#96","江苏 2023 B类 行测#92","江苏 2024 A类 行测#94","江苏 2025 B类 行测#94"],"units":[["江苏 2023 A类 行测#96"],["江苏 2023 B类 行测#92"],["江苏 2024 A类 行测#94"],["江苏 2025 B类 行测#94"]]}]}};
